/bin/bash -lc "cat <<'EOF' > app/page.tsx
import { revalidatePath } from 'next/cache';
import { cookies } from 'next/headers';

async function toggleNotifications() {
  'use server';
  const store = cookies();
  const current = store.get('notifications')?.value === 'on';
  const next = current ? 'off' : 'on';

  store.set('notifications', next, {
    path: '/',
    sameSite: 'lax',
  });

  revalidatePath('/');
}

export default function Home() {
  const store = cookies();
  const enabled = store.get('notifications')?.value === 'on';

  return (
    <main style={{ fontFamily: 'system-ui, sans-serif', padding: '2rem' }}>
      <h1>Settings</h1>
      <p>
        Notifications are <strong>{enabled ? 'On' : 'Off'}</strong>.
      </p>
      <form action={toggleNotifications}>
        <button type=\"submit\">
          Turn {enabled ? 'off' : 'on'} notifications
        </button>
      </form>
    </main>
  );
}
EOF"
